  assert.equal(packages(0, 1000, 250), 0);
  assert.equal(packages(1, 1000, 250), 250);
  assert.equal(packages(1000, 1000, 250), 250);
  assert.equal(packages(1001, 1000, 250), 500);
  assert.equal(packages(2500, 1000, 250), 750);
